#![no_std]
#![no_main]
// Dedicated termination, lifecycle, and StorageServer evidence compile out
// parts of the normal UI/resident validators. Keep default builds strict while
// allowing those feature slices to retain shared implementation they do not
// execute.
#![cfg_attr(
    any(
        bndroid_storage_irq_timeout_profile,
        feature = "process-terminate-self-test",
        feature = "app-lifecycle-runtime",
        feature = "mobile-ui-runtime",
        feature = "storage-server-runtime"
    ),
    allow(dead_code)
)]

#[cfg(all(
    feature = "mobile-ui-runtime",
    any(
        feature = "app-lifecycle-runtime",
        feature = "storage-server-runtime",
        feature = "ui-stale-present-evidence"
    )
))]
compile_error!(
    "mobile-ui-runtime is an isolated local preview and cannot be combined with lifecycle, storage, or stale-present evidence runtimes"
);

