                && processes.resident_surface_capability_session_id == 1
                && processes.resident_surface_capability_owner_pid == recovery.surface_pid
                && processes.resident_input_capability_count == 1
                && processes.resident_input_capability_session_id == 1
                && processes.resident_input_capability_owner_pid == recovery.old_input_pid;
