                && broker.session_id == 1
                && broker.process_id == recovery.old_input_pid
                && broker.acquisition_floor == 0
                && broker.next_session_id == 2
                && broker.next_sequence == 1
                && broker.releases == 0
                && broker.unbound_dropped == 0
                && broker.queue.enqueued == 0
                && broker.queue.dequeued == 0
                && broker.queue.pending == 0
                && broker.queue.high_watermark == 0;
