                || recovery.old_input_session != 1
                || recovery.old_route_epoch != 1
                || recovery.old_floor != 0
                || recovery.permission_audits != 1
                || recovery.permission_caller_pid != recovery.surface_pid
                || recovery.permission_handles_delta != 0
                || recovery.permission_sessions_delta != 0
                || recovery.bir_messages != 3
                || recovery.bip_messages != 1
