                && broker.session_id == 2
                && broker.process_id == recovery.new_input_pid
                && broker.acquisition_floor == 1
                && broker.next_session_id == 3
                && broker.next_sequence == 2
                && broker.releases == 1
                && broker.queue.enqueued == 1
