            && processes.resident_graphics_buffer_owners_valid
            && processes.resident_graphics_buffer_rights_valid
            && processes.graphics_mapping_maps == 2
            && processes.graphics_mapping_unmaps == 0
            && processes.graphics_mapping_protects == 18
