            && lifecycle.crashes == 0
            && lifecycle.commands == 2
            && lifecycle.acks == 2
            && lifecycle.request_actions == EXPECTED_ACTIONS
            && lifecycle.command_actions == EXPECTED_ACTIONS
            && lifecycle.ack_actions == EXPECTED_ACTIONS
            && lifecycle.transactions == 2
            && lifecycle.completed == 2
            && lifecycle.first_app_pid == recovery.app_pid
            && lifecycle.last_app_pid == recovery.app_pid
            && lifecycle.first_sender_pid == recovery.launcher_pid
            && lifecycle.last_sender_pid == recovery.init_pid
            && ui_supervisor.messages == 4
            && ui_supervisor.errors == 0
            && ui_supervisor.byte_messages == 3
            && ui_supervisor.transfer_messages == 1
            && ui_supervisor.commands == 2
            && ui_supervisor.acks == 2
            && ui_supervisor.owner_deaths == 0
            && ui_supervisor.operations == EXPECTED_SUPERVISOR_OPERATIONS
            && ui_supervisor.transactions == 2
            && ui_supervisor.completed == 2
            && ui_supervisor.first_sender_pid == recovery.init_pid
