            && recovery.permission_handles_delta == 0
            && recovery.permission_sessions_delta == 0
            && recovery.backoff_requests == 1
            && recovery.backoff_timeouts == 1
            && recovery.backoff_requested_ns == 30_000_000
            && recovery.backoff_timeout_baseline == 0
            && recovery.backoff_timeout_observed == 1
            && !recovery.backoff_early_spawn
            && recovery.gap_output_slot == 0
