    let dynamic_contexts = scheduler::live_dynamic_user_context_count();
    let dynamic_kernel_stacks = scheduler::live_dynamic_kernel_stack_count();
    let el0_storage = !cfg!(bndroid_storage_irq_timeout_profile);
